<script lang="ts">
 import {onMount} from 'svelte';import {goto} from '$app/navigation';import {Button} from '$lib/components/ui/button';import {Input} from '$lib/components/ui/input';import {request} from '../api';
 let preferences=$state<any>(null),busy=$state(false),error=$state(''),notice=$state(''),confirmation=$state<'history'|'delete'|''>(''),password=$state(''),code=$state('');
 onMount(()=>{void request('/settings/preferences').then(v=>preferences=v).catch(e=>error=e.message);});
 async function changeHistory(){busy=true;error='';try{preferences=await request('/settings/preferences',{history_enabled:!preferences.history_enabled},'PATCH');notice=preferences.history_enabled?'Viewing history is on.':'New viewing history is paused.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function confirm(){busy=true;error='';try{if(confirmation==='history'){await request('/viewer/history',{},'DELETE');notice='Viewing history cleared.';confirmation='';}else{await request('/account/deletion',{password,code});await goto('/login');location.reload();}}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="page-heading"><h1>Privacy</h1><p>Control your viewing history and account.</p></div>{#if error}<p class="cloud-alert" role="alert">{error}</p>{/if}{#if notice}<p class="cloud-notice" role="status">{notice}</p>{/if}
<section><h2>Viewing history</h2><p>Save your place and return to videos you've watched. Pausing history doesn't change your purchases or saved projects.</p>{#if preferences}<Button variant="outline" disabled={busy} onclick={changeHistory}>{preferences.history_enabled?'Pause viewing history':'Turn on viewing history'}</Button>{/if}<Button variant="ghost" disabled={busy} onclick={()=>confirmation='history'}>Clear viewing history</Button></section>
<section><h2>Request account deletion</h2><p>This submits a deletion request and signs you out of all sessions. Financial and legal records follow the platform retention policy.</p><Button variant="destructive" disabled={busy} onclick={()=>confirmation='delete'}>Request deletion</Button></section>
{#if confirmation}<section class="privacy-confirm" aria-label="Confirm privacy action"><h2>{confirmation==='history'?'Clear your viewing history?':'Request deletion of your account?'}</h2><p>{confirmation==='history'?'This cannot be undone. Your public view counts and financial records are retained.':'You will be signed out of all sessions. This is a deletion request, not an immediate erasure of all records.'}</p>{#if confirmation==='delete'}<label for="delete-password">Current password</label><Input id="delete-password" type="password" bind:value={password} autocomplete="current-password"/><label for="delete-code">Authenticator code, if enabled</label><Input id="delete-code" bind:value={code} autocomplete="one-time-code" inputmode="numeric" maxlength={6}/><p>A recent passkey sign-in can confirm your second factor. <a href="/login?returnTo=%2Fsettings%2Fprivacy">Sign in with your passkey</a></p>{/if}<div><Button variant={confirmation==='delete'?'destructive':'outline'} disabled={busy||(confirmation==='delete'&&!password)} onclick={confirm}>{busy?'Working…':'Confirm'}</Button><Button variant="ghost" disabled={busy} onclick={()=>confirmation=''}>Cancel</Button></div></section>{/if}
<style>section{border-top:1px solid var(--border);padding:26px 0}h2{font-size:16px;font-weight:600;margin:0 0 12px}p{font-size:13px;line-height:1.8;color:var(--muted-foreground);max-width:65ch;margin-bottom:18px}section>:global(button){margin-right:10px;min-height:40px}.privacy-confirm{background:var(--muted);padding:20px;border-radius:10px;margin-top:14px}.privacy-confirm>div{display:flex;gap:10px}</style>
